function validate([names, heights]) {
  if (names.length !== heights.length) return 'names and heights must have the same length.';
  if (names.length < 1 || names.length > 1000) return 'There are 1 to 1000 people.';
  if (names.some(s => typeof s !== 'string' || !/^[A-Za-z]{1,20}$/.test(s))) return 'Each name has 1 to 20 English letters.';
  if (heights.some(h => !Number.isInteger(h) || h < 1 || h > 100000)) return 'Each height is between 1 and 100000.';
  if (new Set(heights).size !== heights.length) return 'All heights must be different.';
  return null;
}

