function sortPeople(names, heights) {
  const people = names.map((name, i) => [name, heights[i]]);
  for (let i = 0; i < people.length; i++) {
    let tallest = i;
    for (let j = i + 1; j < people.length; j++) if (people[j][1] > people[tallest][1]) tallest = j;
    const temp = people[i]; people[i] = people[tallest]; people[tallest] = temp;
  }
  return people.map(p => p[0]);
}

