function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const pool = ['Bob', 'Ann', 'bob', 'Z', 'Eve'];
  const randomName = () => {
    const length = 1 + Math.floor(rand() * 20);
    let s = '';
    for (let k = 0; k < length; k++) s += letters[Math.floor(rand() * letters.length)];
    return s;
  };
  const names = Array.from({ length: n }, () => size === 'small' && rand() < 0.6 ? pool[Math.floor(rand() * pool.length)] : randomName());
  const maxHeight = size === 'large' ? 100000 : (rand() < 0.5 ? 12 : 100000);
  const used = new Set();
  const heights = [];
  while (heights.length < n) {
    const h = 1 + Math.floor(rand() * maxHeight);
    if (!used.has(h)) { used.add(h); heights.push(h); }
  }
  return [names, heights];
}
